import copy

def validate_handoff(envelope, expected_specialist, run_id, case_id):
    if type(envelope) is not dict:
        raise TypeError('envelope_not_dict')
    if any(type(value) is not str for value in (expected_specialist, run_id, case_id)):
        raise TypeError('identity_not_string')
    if not expected_specialist.strip() or not run_id.strip() or not case_id.strip():
        raise ValueError('identity_blank')
    roles = {'document', 'sql', 'supplier_risk', 'commercial'}
    if expected_specialist not in roles:
        raise ValueError('specialist_unknown')
    if set(envelope) != {'run_id', 'case_id', 'specialist', 'payload'}:
        raise ValueError('envelope_shape_invalid')
    if type(envelope['payload']) is not dict:
        raise TypeError('payload_not_dict')
    for key in ('run_id', 'case_id', 'specialist'):
        if type(envelope[key]) is not str:
            raise TypeError('envelope_identity_not_string')
    if envelope['specialist'] != expected_specialist:
        raise ValueError('specialist_mismatch')
    if envelope['run_id'] != run_id:
        raise ValueError('run_mismatch')
    if envelope['case_id'] != case_id:
        raise ValueError('case_mismatch')
    return copy.deepcopy(envelope['payload'])

def minimal_assignment(case, specialist):
    if type(case) is not dict or type(specialist) is not str:
        raise TypeError('assignment_input_invalid')
    if set(case) != {'case_id','purchase_order_id','selected_supplier_id','sources'}:
        raise ValueError('case_shape_invalid')
    if type(case['sources']) is not dict:
        raise TypeError('sources_not_dict')
    if set(case['sources']) != {'document','sql','supplier_risk'}:
        raise ValueError('sources_shape_invalid')
    values = (case['case_id'], case['purchase_order_id'], case['selected_supplier_id'], *case['sources'].values())
    if any(type(value) is not str for value in values):
        raise TypeError('identifier_not_string')
    if any(not value.strip() for value in values):
        raise ValueError('identifier_blank')
    if specialist not in {'document','sql','supplier_risk'}:
        raise ValueError('specialist_unknown')
    common = {'case_id': case['case_id'], 'source_id': case['sources'][specialist]}
    if specialist == 'document':
        return {**common, 'purchase_order_id': case['purchase_order_id']}
    if specialist == 'sql':
        return {**common, 'purchase_order_id': case['purchase_order_id'], 'selected_supplier_id': case['selected_supplier_id']}
    return {**common, 'selected_supplier_id': case['selected_supplier_id']}

import copy

def validate_result(result, expected_specialist, run_id, case_id):
    if type(result) is not dict:
        raise TypeError('result_not_dict')
    if set(result) != {'specialist','run_id','case_id','data'}:
        raise ValueError('result_shape_invalid')
    expected_values = (expected_specialist, run_id, case_id)
    if any(type(value) is not str for value in expected_values):
        raise TypeError('expected_identity_invalid')
    if any(not value.strip() for value in expected_values):
        raise ValueError('expected_identity_blank')
    roles = {'document','sql','supplier_risk','commercial'}
    if expected_specialist not in roles:
        raise ValueError('specialist_unknown')
    if type(result['data']) is not dict:
        raise TypeError('result_data_not_dict')
    for key in ('specialist','run_id','case_id'):
        if type(result[key]) is not str:
            raise TypeError('result_identity_invalid')
    if result['specialist'] != expected_specialist:
        raise ValueError('result_specialist_mismatch')
    if result['run_id'] != run_id:
        raise ValueError('result_run_mismatch')
    if result['case_id'] != case_id:
        raise ValueError('result_case_mismatch')
    return copy.deepcopy(result['data'])

def plan_stages(requested):
    if type(requested) is not list:
        raise TypeError('requested_not_list')
    if any(type(role) is not str for role in requested):
        raise TypeError('role_not_string')
    expected = {'document','sql','supplier_risk','commercial'}
    if len(set(requested)) != len(requested):
        raise ValueError('duplicate_role')
    if set(requested) != expected:
        raise ValueError('role_set_invalid')
    return (('document','sql','supplier_risk'),('commercial',))

def bounded_batches(roles, max_workers):
    if type(roles) is not list or type(max_workers) is not int:
        raise TypeError('dispatch_type_invalid')
    if any(type(role) is not str for role in roles):
        raise TypeError('role_not_string')
    if not roles:
        raise ValueError('roles_empty')
    if max_workers < 1 or max_workers > 3:
        raise ValueError('max_workers_out_of_range')
    allowed = {'document','sql','supplier_risk'}
    if any(role not in allowed for role in roles):
        raise ValueError('role_unknown')
    if len(set(roles)) != len(roles):
        raise ValueError('duplicate_role')
    return tuple(tuple(roles[index:index + max_workers]) for index in range(0, len(roles), max_workers))

import copy

def collect_declared(declared, completed):
    if type(declared) is not list or type(completed) is not dict:
        raise TypeError('collection_input_invalid')
    if not declared:
        raise ValueError('declared_empty')
    if any(type(role) is not str for role in declared):
        raise TypeError('role_not_string')
    if len(set(declared)) != len(declared):
        raise ValueError('duplicate_role')
    if any(role not in {'document','sql','supplier_risk'} for role in declared):
        raise ValueError('role_unknown')
    if set(completed) != set(declared):
        raise ValueError('completed_keys_mismatch')
    if any(type(value) is not dict for value in completed.values()):
        raise TypeError('finding_not_dict')
    return tuple((role, copy.deepcopy(completed[role])) for role in declared)

def failure_outcome(outcomes):
    if type(outcomes) is not list:
        raise TypeError('outcomes_not_list')
    expected = ['document','sql','supplier_risk']
    if len(outcomes) != 3:
        raise ValueError('outcome_count_invalid')
    for index, outcome in enumerate(outcomes):
        if type(outcome) is not dict:
            raise TypeError('outcome_not_dict')
        if set(outcome) != {'specialist','status','code'}:
            raise ValueError('outcome_shape_invalid')
        if type(outcome['specialist']) is not str or outcome['specialist'] != expected[index]:
            raise ValueError('outcome_order_invalid')
        if outcome['status'] == 'ok':
            if outcome['code'] is not None:
                raise ValueError('ok_code_invalid')
        elif outcome['status'] == 'technical_failure':
            if type(outcome['code']) is not str or not outcome['code'].strip():
                raise ValueError('failure_code_invalid')
        else:
            raise ValueError('outcome_status_invalid')
    for outcome in outcomes:
        if outcome['status'] == 'technical_failure':
            return {'status':'failed','report':None,'failure_reason':f"{outcome['specialist']}:{outcome['code']}"}
    return {'status':'ready_for_commercial','report':None,'failure_reason':None}

from decimal import Decimal

def commercial_recommendation(terms_found, threshold, variance, supplier_status, risk_level):
    if type(terms_found) is not bool or type(variance) is not Decimal:
        raise TypeError('commercial_input_type_invalid')
    if type(supplier_status) is not str or type(risk_level) is not str:
        raise TypeError('commercial_label_type_invalid')
    if supplier_status not in {'active','inactive'} or risk_level not in {'low','elevated'}:
        raise ValueError('commercial_label_invalid')
    if terms_found:
        if type(threshold) is not Decimal:
            raise TypeError('threshold_not_decimal')
        if threshold < 0:
            raise ValueError('threshold_negative')
    elif threshold is not None:
        raise ValueError('missing_terms_threshold_present')
    if not terms_found:
        return 'needs_human'
    if supplier_status == 'inactive' or risk_level == 'elevated':
        return 'review_required'
    if variance > threshold:
        return 'review_required'
    return 'no_review'

from decimal import Decimal, ROUND_HALF_EVEN, localcontext

def price_variance(current_price, reference_price):
    if type(current_price) is not Decimal or type(reference_price) is not Decimal:
        raise TypeError('price_not_decimal')
    if current_price <= 0 or reference_price <= 0:
        raise ValueError('price_not_positive')
    with localcontext() as context:
        context.prec = 28
        value = (current_price - reference_price) / reference_price * Decimal('100')
        return value.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)

def validate_sources(sources):
    if type(sources) is not list:
        raise TypeError('sources_not_list')
    expected = ('document','sql','risk_register')
    if len(sources) != 3:
        raise ValueError('source_count_invalid')
    ids = []
    result = []
    for index, source in enumerate(sources):
        if type(source) is not dict:
            raise TypeError('source_not_dict')
        if set(source) != {'kind','source_id','digest'}:
            raise ValueError('source_shape_invalid')
        if any(type(source[key]) is not str for key in source):
            raise TypeError('source_value_not_string')
        if source['kind'] != expected[index]:
            raise ValueError('source_kind_mismatch')
        if not source['source_id'].strip():
            raise ValueError('source_id_blank')
        digest = source['digest']
        if len(digest) != 64 or any(char not in '0123456789abcdef' for char in digest):
            raise ValueError('source_digest_invalid')
        ids.append(source['source_id'])
        result.append((source['kind'],source['source_id'],digest[:12]))
    if len(set(ids)) != len(ids):
        raise ValueError('source_id_duplicate')
    return tuple(result)

import copy

def correlate_findings(findings, run_id, case_id):
    if type(findings) is not list:
        raise TypeError('findings_not_list')
    if type(run_id) is not str or type(case_id) is not str:
        raise TypeError('identity_not_string')
    if not run_id.strip() or not case_id.strip():
        raise ValueError('identity_blank')
    if len(findings) != 3:
        raise ValueError('finding_count_invalid')
    by_role = {}
    for finding in findings:
        if type(finding) is not dict:
            raise TypeError('finding_not_dict')
        if set(finding) != {'specialist','run_id','case_id','data'}:
            raise ValueError('finding_shape_invalid')
        if any(type(finding[key]) is not str for key in ('specialist','run_id','case_id')):
            raise TypeError('finding_identity_invalid')
        if type(finding['data']) is not dict:
            raise TypeError('finding_data_not_dict')
        role = finding['specialist']
        if role not in {'document','sql','supplier_risk'} or role in by_role:
            raise ValueError('finding_role_invalid')
        if finding['run_id'] != run_id:
            raise ValueError('finding_run_mismatch')
        if finding['case_id'] != case_id:
            raise ValueError('finding_case_mismatch')
        by_role[role] = finding['data']
    if set(by_role) != {'document','sql','supplier_risk'}:
        raise ValueError('finding_set_incomplete')
    suppliers = []
    for role in ('sql','supplier_risk'):
        supplier = by_role[role].get('supplier_id')
        if type(supplier) is not str or not supplier.strip():
            raise ValueError('supplier_id_invalid')
        suppliers.append(supplier)
    if suppliers[0] != suppliers[1]:
        raise ValueError('supplier_mismatch')
    return tuple(copy.deepcopy(by_role[role]) for role in ('document','sql','supplier_risk'))

def build_evidence(findings):
    if type(findings) is not list:
        raise TypeError('findings_not_list')
    expected = (('document','document'),('sql','sql'),('supplier_risk','risk_register'))
    if len(findings) != 3:
        raise ValueError('finding_count_invalid')
    evidence = []
    source_ids = []
    for finding, (role, kind) in zip(findings, expected):
        if type(finding) is not dict or set(finding) != {'specialist','source'}:
            raise ValueError('finding_shape_invalid')
        if finding['specialist'] != role:
            raise ValueError('finding_order_invalid')
        source = finding['source']
        if type(source) is not dict:
            raise TypeError('source_not_dict')
        if set(source) != {'kind','source_id','digest'}:
            raise ValueError('source_shape_invalid')
        if any(type(source[key]) is not str for key in source):
            raise TypeError('source_value_invalid')
        if source['kind'] != kind or not source['source_id'].strip():
            raise ValueError('source_identity_invalid')
        digest = source['digest']
        if len(digest) != 64 or any(char not in '0123456789abcdef' for char in digest):
            raise ValueError('source_digest_invalid')
        source_ids.append(source['source_id'])
        evidence.append(f"{kind}:{source['source_id']}:{digest[:12]}")
    if len(set(source_ids)) != 3 or len(set(evidence)) != 3:
        raise ValueError('evidence_not_unique')
    return tuple(evidence)

import re

def sanitize_failure(controlled_code, exception_name):
    if controlled_code is not None and type(controlled_code) is not str:
        raise TypeError('controlled_code_invalid')
    if exception_name is not None and type(exception_name) is not str:
        raise TypeError('exception_name_invalid')
    if (controlled_code is None) == (exception_name is None):
        raise ValueError('exactly_one_failure_input_required')
    if controlled_code is not None:
        if re.fullmatch(r'[a-z][a-z0-9_]*', controlled_code) is None:
            raise ValueError('controlled_code_malformed')
        return controlled_code
    if re.fullmatch(r'[A-Z][A-Za-z0-9_]*', exception_name) is None:
        raise ValueError('exception_name_malformed')
    return f'unexpected_{exception_name}'

def build_report(run_id, case_id, recommendation, summary, evidence):
    if any(type(value) is not str for value in (run_id,case_id,recommendation,summary)):
        raise TypeError('report_value_not_string')
    if not run_id.strip() or not case_id.strip() or not summary.strip():
        raise ValueError('report_value_blank')
    if len(summary) > 600:
        raise ValueError('summary_too_long')
    if recommendation not in {'no_review','review_required','needs_human'}:
        raise ValueError('recommendation_invalid')
    if type(evidence) is not list:
        raise TypeError('evidence_not_list')
    if len(evidence) != 3 or any(type(item) is not str for item in evidence):
        raise ValueError('evidence_shape_invalid')
    if any(not item.strip() for item in evidence) or len(set(evidence)) != 3:
        raise ValueError('evidence_not_unique')
    return {'run_id':run_id,'case_id':case_id,'recommendation':recommendation,'summary':summary,'evidence':tuple(evidence),'requires_human_approval':True,'status':'awaiting_approval'}

