def compare_structures(supervisor, workflow):
    for value in (supervisor, workflow):
        if type(value) is not dict:
            raise TypeError('architecture_not_dict')
        if set(value) != {'report','handoffs','dependency_stages'}:
            raise ValueError('architecture_shape_invalid')
        if value['report'] is not None and type(value['report']) is not dict:
            raise TypeError('report_invalid')
        for key in ('handoffs','dependency_stages'):
            if type(value[key]) is not int:
                raise TypeError('metric_not_int')
            if value[key] < 0:
                raise ValueError('metric_negative')
    return {'outcome_equal':supervisor['report']==workflow['report'],'supervisor_handoffs':supervisor['handoffs'],'workflow_handoffs':workflow['handoffs'],'supervisor_dependency_stages':supervisor['dependency_stages'],'workflow_dependency_stages':workflow['dependency_stages'],'measured_latency_ms':None}

def choose_architecture(requirements):
    if type(requirements) is not dict:
        raise TypeError('requirements_not_dict')
    expected = {'distinct_context','separate_governance','independent_work','coordination_cost_justified'}
    if set(requirements) != expected:
        raise ValueError('requirements_shape_invalid')
    if any(type(value) is not bool for value in requirements.values()):
        raise TypeError('requirement_not_bool')
    boundary = requirements['distinct_context'] or requirements['separate_governance']
    if boundary and requirements['independent_work'] and requirements['coordination_cost_justified']:
        return 'supervisor_specialists'
    return 'single_workflow'

def validate_registry(registry):
    if type(registry) is not dict:
        raise TypeError('registry_not_dict')
    roles = ('document','sql','supplier_risk','commercial')
    if set(registry) != set(roles):
        raise ValueError('registry_roles_invalid')
    if any(not callable(registry[role]) for role in roles):
        raise TypeError('registry_value_not_callable')
    return roles

