def retry_candidates(failures, max_attempts):
    if type(failures) is not list or type(max_attempts) is not int:
        raise TypeError('retry_input_invalid')
    if max_attempts < 1 or max_attempts > 3:
        raise ValueError('max_attempts_invalid')
    roles = {'document','sql','supplier_risk','commercial'}
    codes = {'service_unavailable','timeout','identity_mismatch','type_mismatch','digest_mismatch'}
    retryable = {'service_unavailable','timeout'}
    seen = set()
    result = []
    for failure in failures:
        if type(failure) is not dict:
            raise TypeError('failure_not_dict')
        if set(failure) != {'specialist','code','attempts'}:
            raise ValueError('failure_shape_invalid')
        if type(failure['specialist']) is not str or type(failure['code']) is not str or type(failure['attempts']) is not int:
            raise TypeError('failure_value_invalid')
        if failure['specialist'] not in roles or failure['specialist'] in seen:
            raise ValueError('failure_role_invalid')
        if failure['code'] not in codes:
            raise ValueError('failure_code_invalid')
        if failure['attempts'] < 1 or failure['attempts'] > max_attempts:
            raise ValueError('failure_attempts_invalid')
        seen.add(failure['specialist'])
        if failure['code'] in retryable and failure['attempts'] < max_attempts:
            result.append(failure['specialist'])
    return tuple(result)

def audit_run(result):
    if type(result) is not dict:
        raise TypeError('result_not_dict')
    if set(result) != {'architecture','status','report','findings','metrics','failure_reason'}:
        raise ValueError('result_shape_invalid')
    if result['architecture'] not in {'supervisor_specialists','single_workflow'}:
        raise ValueError('architecture_invalid')
    if type(result['findings']) is not list or type(result['metrics']) is not dict:
        raise TypeError('result_collection_invalid')
    if set(result['metrics']) != {'handoffs','dependency_stages'}:
        raise ValueError('metrics_shape_invalid')
    for value in result['metrics'].values():
        if type(value) is not int:
            raise TypeError('metric_not_int')
        if value < 0:
            raise ValueError('metric_negative')
    approval = False
    if result['status'] == 'awaiting_approval':
        report = result['report']
        if type(report) is not dict or set(report) != {'recommendation','requires_human_approval'}:
            raise ValueError('success_report_invalid')
        if report['recommendation'] not in {'no_review','review_required','needs_human'}:
            raise ValueError('recommendation_invalid')
        if report['requires_human_approval'] is not True or result['failure_reason'] is not None:
            raise ValueError('success_fields_invalid')
        approval = True
    elif result['status'] == 'failed':
        if result['report'] is not None or type(result['failure_reason']) is not str or not result['failure_reason'].strip():
            raise ValueError('failed_fields_invalid')
    else:
        raise ValueError('status_invalid')
    return {'architecture':result['architecture'],'status':result['status'],'has_report':result['report'] is not None,'requires_human_approval':approval,'handoffs':result['metrics']['handoffs'],'dependency_stages':result['metrics']['dependency_stages']}
